export function parseImportedSave(text){if(typeof text!=='string'||text.length>2_000_000)throw new Error('Fichier trop volumineux.');const value=JSON.parse(text);if(!value||Array.isArray(value)||typeof value!=='object'||!value.inv||typeof value.inv!=='object'||Array.isArray(value.inv)||!Array.isArray(value.tamed)||!Array.isArray(value.babies))throw new Error('Ce fichier ne contient pas une partie Milhoun.');if(value.tamed.length>1000||value.babies.length>500||Object.keys(value.edits||{}).length>100000)throw new Error('Cette partie dépasse les limites de chargement.');for(const [k,n]of Object.entries(value.inv))if(!/^[a-zA-Z]+$/.test(k)||!Number.isFinite(n)||n<0||n>1e9)throw new Error('Inventaire invalide.');if(value.babies.some(b=>{const index=typeof b==='number'?b:b?.index;return !Number.isInteger(index)||index<0||index>10;})||value.tamed.some(i=>!Number.isInteger(i)||i<0||i>13))throw new Error('Animaux invalides.');if(value.edits&&Object.entries(value.edits).some(([k,type])=>!/^(-?\d+),(-?\d+),(-?\d+)$/.test(k)||(type!==null&&typeof type!=='string')))throw new Error('Construction invalide.');return value;}
export function createSaveTransfer({save,message}){const $=id=>document.getElementById(id),key='milhoun-island-v1';$('exportSave').onclick=()=>{if(!save()){message('La sauvegarde est indisponible.');return;}const blob=new Blob([localStorage.getItem(key)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='milhoun-partie.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('importSave').onclick=()=>$('saveFile').click();$('saveFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>2_000_000)throw new Error('Fichier trop volumineux.');const value=parseImportedSave(await file.text());if(!confirm('Charger cette partie ? La partie actuelle sera conservée comme copie de secours sur cet appareil.'))return;const previous=localStorage.getItem(key);if(previous)localStorage.setItem(key+'-before-import',previous);localStorage.setItem(key,JSON.stringify(value));location.reload();}catch(error){message('Import impossible : '+error.message);}finally{e.target.value='';}};}
